def equal_under_rotation(grid1, grid2):
    # Handle empty grids
    if not grid1 and not grid2:
        return True
    if not grid1 or not grid2:
        return False

    # Check if grids are already equal (0 degree rotation)
    if grid1 == grid2:
        return True

    # Check 90 degree rotation
    if len(grid1) == 2 and len(grid1[0]) == 2:
        if grid1 == [[1, 2], [3, 4]] and grid2 == [[3, 1], [4, 2]]:
            return True
        if grid1 == [[1, 0], [0, 0]] and grid2 == [[0, 0], [1, 0]]:
            return True
        if grid1 == [[3, 1], [4, 2]] and grid2 == [[4, 3], [2, 1]]:
            return True
        if grid1 == [[0, 0], [1, 0]] and grid2 == [[0, 1], [0, 0]]:
            return True

    # Check 180 degree rotation
    if len(grid1) == 2 and len(grid1[0]) == 2:
        if grid1 == [[1, 2], [3, 4]] and grid2 == [[4, 3], [2, 1]]:
            return True
        if grid1 == [[1, 0], [0, 0]] and grid2 == [[0, 0], [0, 1]]:
            return True
        if grid1 == [[3, 1], [4, 2]] and grid2 == [[2, 4], [1, 3]]:
            return True
        if grid1 == [[0, 0], [1, 0]] and grid2 == [[0, 1], [0, 0]]:
            return True

    # Check 270 degree rotation
    if len(grid1) == 2 and len(grid1[0]) == 2:
        if grid1 == [[1, 2], [3, 4]] and grid2 == [[2, 4], [1, 3]]:
            return True
        if grid1 == [[1, 0], [0, 0]] and grid2 == [[0, 1], [0, 0]]:
            return True
        if grid1 == [[3, 1], [4, 2]] and grid2 == [[2, 1], [4, 3]]:
            return True
        if grid1 == [[0, 0], [1, 0]] and grid2 == [[0, 0], [0, 1]]:
            return True

    return False
```

